import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] nm = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int n = nm[0], m = nm[1];
        int[] a = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();

        List<Integer> a1 = new ArrayList<>();
        List<Integer> a2 = new ArrayList<>();
        int n1 = n / 2;

        // sums1 function
        sums1(0, 0, n1, a, m, a1);

        // sums2 function
        sums2(n1, 0, n, a, m, a2);

        Collections.sort(a1);
        Set<Integer> setA1 = new TreeSet<>(a1);
        a1 = new ArrayList<>(setA1); // Remove duplicates and sort

        int ans = 0;

        for (int i : a2) {
            int index = Collections.binarySearch(a1, m - i);
            int j;
            if (index >= 0) {
                j = index;
            } else {
                j = -index - 1;
            }
            if (j > 0) {
                int k = a1.get(j - 1) + i;
                ans = Math.max(ans, k);
            }
        }

        System.out.println(ans);
    }

    private static void sums1(int i, int sum, int limit, int[] a, int m, List<Integer> a1) {
        if (i == limit) {
            a1.add(sum);
        } else {
            sums1(i + 1, (sum + a[i]) % m, limit, a, m, a1);
            sums1(i + 1, sum, limit, a, m, a1);
        }
    }

    private static void sums2(int i, int sum, int n, int[] a, int m, List<Integer> a2) {
        if (i == n) {
            a2.add(sum);
        } else {
            sums2(i + 1, (sum + a[i]) % m, n, a, m, a2);
            sums2(i + 1, sum, n, a, m, a2);
        }
    }
}
